24	    /** Stamp a single owner's household member count. */
25	    static void stamp(Owner owner, OwnerRepository ownerRepository) {
26	        List<Owner> all = new ArrayList<>();
27	        ownerRepository.findAll().forEach(all::add);
28	        owner.setHouseholdMemberCount(count(owner, all));
29	    }
